SRCF = "карточка Яндекс Карт «{}» ({}), поиск по району"
PT = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "sections_1111z_points.json")))
PHONE, SRC = {}, {}
for s in SPEC:
    pid, name, typ, a0, a1, cats, tags, addr, how, plus, minus, price, note, site, phone, extra = s
    if pid not in PT:
        continue
    lat, lon, acc = PT[pid]
    src = SRCF.format(name.split(" (")[0], addr) + ("; " + extra if extra else "")
    SRC[pid] = src
    B.add(pid, name, typ, (lat, lon, metro(lat, lon), acc), addr, a0, a1, (45, 90), price, note, plus, minus, cats, site,
          src, tags=tags)
    r = B.R[-1]
    if how:
        r["Как найти"] = how
    r["Взрослый билет, ₽"] = None
    if phone:
        PHONE[pid] = phone
ROWS = B.R
if os.environ.get("ONLY"):
    ROWS = [r for r in ROWS if r["id"] in os.environ["ONLY"].split(",")]

if __name__ == "__main__":
    B.ROWS = ROWS
    sys.argv[0] = B.__file__
    src = open(B.__file__).read().split('if __name__ == "__main__":')[1]
    import textwrap
    exec(textwrap.dedent(src), {**B.__dict__, "ROWS": ROWS})
